// Split uploaded PDF files into separate items
// The webapp sends files as FormData with keys 'file1', 'file2'
const items = [];
const inputItem = $input.first();
const binary = inputItem.binary;

if (!binary || Object.keys(binary).length === 0) {
  throw new Error('No PDF files received. Please upload at least one PDF.');
}

for (const [key, binaryData] of Object.entries(binary)) {
  items.push({
    json: {
      fileKey: key,
      fileName: binaryData.fileName || key
    },
    binary: {
      data: binaryData
    }
  });
}

return items;

// Parse AI agent output into structured results array
const results = [];

for (const item of $input.all()) {
  let output = item.json.output || item.json.text || '';

  // Remove markdown code blocks if AI wrapped the JSON in ```json ... ```
  output = output.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

  try {
    const parsed = JSON.parse(output);
    results.push(parsed);
  } catch (e) {
    // If direct parse fails, try to find JSON object in the text
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        results.push(JSON.parse(jsonMatch[0]));
      } catch (e2) {
        results.push({ extractionError: 'Could not parse AI response', rawOutput: output });
      }
    } else {
      results.push({ extractionError: 'No JSON found in AI response', rawOutput: output });
    }
  }
}

// Return as { results: [...] } so the webapp displays each PDF separately
return [{ json: { results } }];
